/* ==UserStyle==
@name         Rainbow Background
@namespace    userstyles
@version      1.0
@description  Regenbogen-Hintergrund für alle Webseiten
==/UserStyle== */

html, body {
    min-height: 100% !important;
    background: linear-gradient(
        270deg,
        #ff0000,
        #ff7f00,
        #ffff00,
        #00ff00,
        #0000ff,
        #4b0082,
        #9400d3
    ) !important;
    background-size: 1400% 1400% !important;
    animation: rainbowBG 15s ease infinite !important;
}

/* Animation */
@keyframes rainbowBG {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}

/* Optional: Text besser lesbar */
body * {
    background-color: transparent !important;
}
